function taskPagingProbeSource(consumer){
 return `'use client';
import {useLayoutEffect,useState} from 'react';
// Controlled consumer only. AccountWorkspace and its task pager are exact
// copies; this probe deliberately leaves its read button enabled while busy
// so the parent must reject the read rather than relying on a disabled child.
export function ${consumer.exportName}({tasks,taskPaging,onLoadMoreTasks,onTaskReadBusy,onPending}){
 const[draft,setDraft]=useState(()=>({id:crypto.randomUUID(),text:'',quantity:'1.250',taskId:'task_001'})),[phase,setPhase]=useState('draft'),[result,setResult]=useState('idle');
 useLayoutEffect(()=>{onPending?.(Boolean(draft.text)||phase!=='draft');return()=>onPending?.(false);},[draft.text,phase,onPending]);
 useLayoutEffect(()=>{onTaskReadBusy?.(phase!=='draft');return()=>onTaskReadBusy?.(false);},[phase,onTaskReadBusy]);
 return <section data-task-page-probe="${consumer.name}" data-count={tasks.length} data-cursor={taskPaging.nextCursor||''} data-phase={phase} data-draft-id={draft.id} data-result={result} data-loading={String(taskPaging.loading)} style={{maxWidth:'100%'}}>
  <h3 id="${consumer.heading}">Consumidor sintético ${consumer.name}</h3>
  <p>Prueba aislada del padre real; este formulario no representa permisos ni crea operaciones.</p>
  <button type="button" data-paging-start onClick={()=>setDraft(old=>({...old,text:'Borrador ${consumer.name} conservado sin enviar'}))}>Preparar borrador sintético</button>
  <label>Descripción sintética<textarea data-paging-draft value={draft.text} onChange={event=>setDraft(old=>({...old,text:event.target.value}))} style={{boxSizing:'border-box',width:'100%'}}/></label>
  <label>Cantidad de ensayo<input data-paging-quantity value={draft.quantity} onChange={event=>setDraft(old=>({...old,quantity:event.target.value}))}/></label>
  <label>Tarea de ensayo<select data-paging-selected value={draft.taskId} onChange={event=>setDraft(old=>({...old,taskId:event.target.value}))} style={{maxWidth:'100%'}}>{tasks.map(task=><option key={task.id} value={task.id}>{task.title}</option>)}</select></label>
  <p data-paging-count>{tasks.length} de {taskPaging.totalTasks} tareas</p>
  <p role="status" data-paging-error>{taskPaging.error}</p>
  <div style={{display:'flex',flexWrap:'wrap',gap:8}}>
   <button type="button" data-paging-more onClick={async()=>{setResult('pending');const answer=await onLoadMoreTasks();setResult(String(answer));}}>Consultar página siguiente</button>
   <button type="button" data-paging-saving onClick={()=>setPhase('saving')}>Simular envío pendiente</button>
   <button type="button" data-paging-uncertain onClick={()=>setPhase('uncertain')}>Simular recibo incierto</button>
   <button type="button" data-paging-draft-mode onClick={()=>setPhase('draft')}>Volver al borrador sintético</button>
  </div>
 </section>;
}
`;
}
